(7543679, 1207675, 113411, '<td valign="top">what a perfect shot of a flower! brilliant!</td>', 'what a perfect shot of a flower! brilliant!', '2017-11-09 18:05:16.000000', NULL, 1),
(7543680, 1207695, 115814, '<td valign="top">Well-placed subject for this challenge. From my perspective, however, the soft gradient of the background is disrupted at the bottom by the distant flower, which, to me, fights for attention with the main subject. Still an effective image!</td>', 'Well-placed subject for this challenge. From my perspective, however, the soft gradient of the background is disrupted at the bottom by the distant flower, which, to me, fights for attention with the main subject. Still an effective image!', '2017-11-09 18:06:22.000000', NULL, 1),
(7543681, 1207640, 113411, '<td valign="top">7 for the cuteness factor!</td>', '7 for the cuteness factor!', '2017-11-09 18:06:30.000000', NULL, 1),
(7543682, 1207288, 115814, '<td valign="top">You''ve made a lovely image that conveys a sense of serenity and calm to me. And, although you''ve placed the horizon well below the center line, to my eyes, the trees are close enough together that the overall impression is one of centered composition rather than a more traditional rule of thirds subject placement.</td>', 'You''ve made a lovely image that conveys a sense of serenity and calm to me. And, although you''ve placed the horizon well below the center line, to my eyes, the trees are close enough together that the overall impression is one of centered composition rather than a more traditional rule of thirds subject placement.', '2017-11-09 18:06:31.000000', NULL, 1),
(7543683, 1207429, 113411, '<td valign="top">brilliant shot ...Fine Art!</td>', 'brilliant shot ...Fine Art!', '2017-11-09 18:07:41.000000', NULL, 1),
(7543684, 1207700, 113411, '<td valign="top">wow!!! fabulous shot! brilliant!</td>', 'wow!!! fabulous shot! brilliant!', '2017-11-09 18:08:26.000000', NULL, 1),
